import sys
import json

def solve():
    # Retrieve parameters from input_data
    start_x = int(input_data['start_x'])
    start_y = int(input_data['start_y'])
    target_x = int(input_data['target_x'])
    target_y = int(input_data['target_y'])
    map_id = input_data['map_id']

    # B1F (0_232) verified passable coordinates database
    b1f_tiles = set()

    # 1. B1F Starting Chamber / eastern area
    for y in range(21, 30):
        for x in range(28, 38):
            b1f_tiles.add((x, y))
    # Starting ladder area (33, 25)
    b1f_tiles.add((33, 25))

    # 2. Lower southern corridors and bypass (Y >= 30, Y <= 31)
    for y in [30, 31]:
        for x in range(26, 30):
            b1f_tiles.add((x, y))

    # 3. Far Western lower vertical path (Column 17) on Rows 27-31
    for y in range(27, 32):
        b1f_tiles.add((17, y))
        b1f_tiles.add((16, y)) # wide corridor
        b1f_tiles.add((15, y))
        b1f_tiles.add((14, y))

    # 4. Upper bypass corridor (Rows 18-19, Columns 14-29)
    for y in [18, 19]:
        for x in range(14, 30):
            b1f_tiles.add((x, y))

    # 5. Middle corridor (Rows 10-13, Columns 14-23)
    for y in range(10, 14):
        for x in range(14, 24):
            b1f_tiles.add((x, y))

    # 6. Newly explored western dead-end chamber (Rows 14-21, Columns 14-17)
    for y in range(14, 22):
        for x in range(14, 18):
            b1f_tiles.add((x, y))

    # 7. Newly explored northern bypass/corridor (Rows 2-7, Columns 14-23)
    for y in range(2, 6):
        for x in range(14, 24):
            b1f_tiles.add((x, y))
    for y in [6, 7]:
        for x in range(14, 18):
            b1f_tiles.add((x, y))
        for x in range(20, 24):
            b1f_tiles.add((x, y))

    # 8. Column 17 northern connection (Rows 5-9, Columns 14-17)
    for y in range(5, 10):
        for x in range(14, 17):
            b1f_tiles.add((x, y))

    # 1F (0_82) verified passable coordinates database
    f1_tiles = set()
    # Western starting chamber / corridors (Rows 4-7, Columns 14-28)
    for y in range(4, 8):
        for x in range(14, 29):
            f1_tiles.add((x, y))
    # Eastern starting chamber / corridors (Rows 10-13, Columns 20-33)
    for y in range(10, 14):
        for x in range(20, 34):
            f1_tiles.add((x, y))
    # Northern vertical path (Column 35, Rows 4-12)
    for y in range(4, 13):
        f1_tiles.add((35, y))
    f1_tiles.add((34, 12))
    f1_tiles.add((33, 12))
    f1_tiles.add((33, 11))
    f1_tiles.add((33, 10))
    f1_tiles.add((17, 11))

    # 1F Ladder B branch (Y >= 3, Y <= 15)
    for y in range(3, 16):
        for x in range(4, 8):
            f1_tiles.add((x, y))
    # Wide corridor at Y=6 to Columns 2-10
    for x in range(2, 11):
        f1_tiles.add((x, 6))
    # Southern open path (Rows 16-21, Columns 5-21)
    for y in range(16, 22):
        for x in range(5, 22):
            f1_tiles.add((x, y))
    # Column 16 vertical connection (Rows 14-15, Column 16)
    for y in range(14, 15):
        f1_tiles.add((16, y))

    # Vertical corridor connecting (17, 11) to the southern area (Columns 14-17, Rows 10-15)
    for y in range(10, 16):
        for x in range(14, 18):
            f1_tiles.add((x, y))

    # Column 4 bypass corridor on Rows 16-21
    for y in range(16, 22):
        f1_tiles.add((4, y))

    # Remove blocked Hiker tile (5, 16)
    if (5, 16) in f1_tiles:
        f1_tiles.remove((5, 16))

    # Remove solid wall at Columns 6-7 on Rows 16-17 on 1F
    for y in [16, 17]:
        for x in [6, 7]:
            if (x, y) in f1_tiles:
                f1_tiles.remove((x, y))

    # Choose correct tiles based on map_id
    if map_id == '0_232':
        passable_tiles = b1f_tiles
    elif map_id == '0_82':
        passable_tiles = f1_tiles
    else:
        print(json.dumps([]))
        return

    # BFS pathfinding
    if (start_x, start_y) not in passable_tiles:
        passable_tiles.add((start_x, start_y))
    if (target_x, target_y) not in passable_tiles:
        passable_tiles.add((target_x, target_y))

    queue = [[(start_x, start_y)]]
    visited = {(start_x, start_y)}

    while queue:
        path = queue.pop(0)
        curr_x, curr_y = path[-1]

        if (curr_x, curr_y) == (target_x, target_y):
            buttons = []
            for i in range(len(path) - 1):
                cx, cy = path[i]
                nx, ny = path[i+1]
                if nx == cx + 1:
                    buttons.append('Right')
                elif nx == cx - 1:
                    buttons.append('Left')
                elif ny == cy + 1:
                    buttons.append('Down')
                elif ny == cy - 1:
                    buttons.append('Up')
            print(json.dumps(buttons))
            return

        for dx, dy in [(1,0), (-1,0), (0,1), (0,-1)]:
            nx, ny = curr_x + dx, curr_y + dy
            if (nx, ny) in passable_tiles and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(path + [(nx, ny)])

    print(json.dumps([]))

solve()
